class Solution {
    public Node connect(Node root) {
        if (root == null || (root.left == null && root.right == null)) {
            return root;
        }
        Deque<Node> q = new ArrayDeque<>();
        q.offer(root);
        while (!q.isEmpty()) {
            Node cur = null;
            for (int i = 0, n = q.size(); i < n; ++i) {
                Node node = q.pollFirst();
                if (node.right != null) {
                    q.offer(node.right);
                }
                if (node.left != null) {
                    q.offer(node.left);
                }
                node.next = cur;
                cur = node;
            }
        }
        return root;
    }
}

